import type { NotificationItem } from "./Toast";
import { NotificationContent } from "./Toast";
export interface NotificationCenterProps { items: readonly NotificationItem[]; onAction?: (id: string) => void; onDismiss?: (id: string) => void; onMarkRead?: (id: string) => void; onClear?: () => void; emptyMessage?: string; ariaLabel?: string }
export function NotificationCenter({ items, onAction, onDismiss, onMarkRead, onClear, emptyMessage="No notifications", ariaLabel="Notification history" }: NotificationCenterProps) { return <section className="aui-notification-center" aria-label={ariaLabel}><header><strong>{ariaLabel}</strong>{items.length && onClear ? <button type="button" onClick={onClear}>Clear all</button> : null}</header>{items.length === 0 ? <div className="aui-notification-empty">{emptyMessage}</div> : <ul>{items.map(item=><li key={item.id} className={item.read ? "" : "aui-notification--unread"}><button type="button" className="aui-notification-main" aria-label={item.read ? `Open ${item.title}` : `Mark ${item.title} read`} onClick={()=>onMarkRead?.(item.id)}><NotificationContent item={item} />{item.timestamp ? <time>{item.timestamp}</time>:null}</button><span className="aui-notification-actions">{item.actionLabel?<button type="button" onClick={()=>onAction?.(item.id)}>{item.actionLabel}</button>:null}<button type="button" aria-label={`Remove ${item.title}`} onClick={()=>onDismiss?.(item.id)}>×</button></span></li>)}</ul>}</section>; }
